91	fn load_manifests(manifest_dir: &Utf8Path) -> DistResult<Vec<crate::DistManifest>> {
92	    // This happens on clean builds with no manifests to slurp up, and the dist-dir
93	    // not yet created. In that case there's clearly nothing to import!
94	    if !manifest_dir.exists() {
95	        return Ok(vec![]);
96	    }
97	
98	    // Collect all dist-manifests and fetch the appropriate Mac ones
99	    let mut manifests = vec![];
100	    for file in manifest_dir.read_dir()? {
101	        let path = file?.path();
102	        if let Some(filename) = path.file_name() {
